const MCP_ADDON_NAME = '@storybook/addon-mcp';

/** The default endpoint the MCP addon is served from. */
const DEFAULT_MCP_ENDPOINT = '/mcp';

/** The current version of the runtime instance record schema. */
const SCHEMA_VERSION = 1;

/**
 * Describes whether an AI integration (MCP) addon is available on a running Storybook instance and,
 * if so, where its endpoint lives.
 */
export interface McpMetadata {
  status: 'ready' | 'not-installed';
  endpoint?: string;
}

/** A single addon entry as it appears in a main config `addons` array. */
type AddonEntry = string | { name: string; options?: any };

/** The subset of the resolved main config that is relevant for the registry. */
export interface MainConfigLike {
  addons?: AddonEntry[];
}

/**
 * A record describing a single running Storybook instance. It is serialized to disk so that
 * external tools can discover running instances and determine whether an AI integration addon is
 * available.
 */
export interface RuntimeInstanceRecord {
  /** The version of this record's schema, so consumers can evolve safely. */
  schemaVersion: number;
  /** A unique identifier for this running instance. */
  instanceId: string;
  /** The origin (protocol + host + port) the instance is served from. */
  url: string;
  /** The absolute working directory the instance was started from. */
  cwd: string;
  /** ISO 8601 timestamp of when the instance started. */
  startedAt: string;
  /** ISO 8601 timestamp of when this record was last updated. */
  updatedAt: string;
  /** Metadata about the AI integration (MCP) addon. */
  mcp: McpMetadata;
}

/** Options for {@link createRuntimeInstanceRecord}. */
export interface CreateRuntimeInstanceRecordOptions {
  /** A unique identifier for this running instance. */
  instanceId: string;
  /** The address the instance is served from. Query parameters are stripped. */
  address: string;
  /** The working directory the instance was started from. Resolved to an absolute path. */
  cwd: string;
  /** The current time, used for both `startedAt` and `updatedAt`. */
  now: Date | number | string;
  /** Metadata about the AI integration (MCP) addon. Defaults to `not-installed`. */
  mcp?: McpMetadata;
}

/**
 * Determines whether the `@storybook/addon-mcp` addon is present in the given main config and, if
 * so, which endpoint it is served from.
 *
 * - Returns `{ status: 'not-installed' }` when the addon is absent.
 * - Returns `{ status: 'ready', endpoint: '/mcp' }` when the addon is referenced as a plain string.
 * - Returns `{ status: 'ready', endpoint: <value> }` when the addon is referenced as an object with
 *   a matching `name` and an `options.endpoint`.
 */
export function getMcpMetadataFromMainConfig(mainConfig: MainConfigLike): McpMetadata {
  const addons = mainConfig.addons ?? [];

  for (const addon of addons) {
    if (typeof addon === 'string') {
      if (addon === MCP_ADDON_NAME) {
        return { status: 'ready', endpoint: DEFAULT_MCP_ENDPOINT };
      }
      continue;
    }

    if (addon && addon.name === MCP_ADDON_NAME) {
      return {
        status: 'ready',
        endpoint: addon.options?.endpoint ?? DEFAULT_MCP_ENDPOINT,
      };
    }
  }

  return { status: 'not-installed' };
}

/**
 * Builds a {@link RuntimeInstanceRecord} from the given options, normalizing the address into an
 * origin, resolving the working directory to an absolute path and formatting the timestamps as ISO
 * 8601 strings.
 */
export function createRuntimeInstanceRecord(
  options: CreateRuntimeInstanceRecordOptions
): RuntimeInstanceRecord {
  const { instanceId, address, cwd, now, mcp } = options;

  const timestamp = new Date(now).toISOString();

  return {
    schemaVersion: SCHEMA_VERSION,
    instanceId,
    url: new URL(address).origin,
    cwd: resolve(cwd),
    startedAt: timestamp,
    updatedAt: timestamp,
    mcp: mcp ? { status: mcp.status, endpoint: mcp.endpoint } : { status: 'not-installed' },
  };
}

/**
 * Atomically writes a {@link RuntimeInstanceRecord} to `<instanceId>.json` inside `registryDir`.
 *
 * The record is first written to a temporary file which is then renamed into place, so an observer
 * of `registryDir` only ever sees the final, complete `.json` file.
 *
 * @returns The absolute path to the written record file.
 */
export async function writeRuntimeInstanceRecord(
  record: RuntimeInstanceRecord,
  registryDir: string
): Promise<string> {
  await mkdir(registryDir, { recursive: true });

  const recordPath = join(registryDir, `${record.instanceId}.json`);
  const tmpPath = `${recordPath}.tmp`;

  await writeFile(tmpPath, JSON.stringify(record, null, 2), 'utf-8');
  await rename(tmpPath, recordPath);

  return recordPath;
}

/** The result of {@link writeStorybookRuntimeInstanceRecord}. */
export interface StorybookRuntimeInstanceRecordHandle {
  /** The absolute path to the written record file. */
  recordPath: string;
  /** Removes the record file from disk. Safe to call multiple times. */
  cleanup: () => Promise<void>;
}

/** Options for {@link writeStorybookRuntimeInstanceRecord}. */
export interface WriteStorybookRuntimeInstanceRecordOptions
  extends CreateRuntimeInstanceRecordOptions {
  /** The directory the record is written to. */
  registryDir: string;
}

/**
 * Higher-level helper managing the full lifecycle of a runtime instance record: it builds the
 * record, writes it to disk and returns a handle that can be used to clean the record up again when
 * the instance stops.
 */
export async function writeStorybookRuntimeInstanceRecord(
  options: WriteStorybookRuntimeInstanceRecordOptions
): Promise<StorybookRuntimeInstanceRecordHandle> {
  const { registryDir, ...recordOptions } = options;

  const record = createRuntimeInstanceRecord(recordOptions);
  const recordPath = await writeRuntimeInstanceRecord(record, registryDir);

  return {
    recordPath,
    cleanup: async () => {
      await rm(recordPath, { force: true });
    },
  };
}
